358	pub fn make_keydown(
359	    on_submit: Callback<String>,
360	    input_value: UseStateHandle<String>,
361	    cmd_history: UseStateHandle<Vec<String>>,
362	    cmd_index: UseStateHandle<Option<usize>>,
363	    completion_candidates: UseStateHandle<Vec<String>>,
364	) -> Callback<KeyboardEvent> {
365	    Callback::from(move |e: KeyboardEvent| {
366	        // Saga 33 step 045/046: Ctrl+Space triggers the
367	        // completion popup -- the IDE standard (VS Code,
368	        // IntelliJ, Emacs). Guarded ahead of the key-string
369	        // match because the trigger is a (modifier, code)
370	        // pair, not a single named key. Tab is reserved for
371	        // browser focus traversal (the step-043 attempt to
372	        // override Tab lost to the browser's default).
373	        if crate::completion::is_completion_trigger(e.ctrl_key(), e.code().as_str()) {
374	            e.prevent_default();
375	            handle_completion(&e, &input_value, &completion_candidates);
376	            return;
377	        }
378	        match e.key().as_str() {
379	            "Enter" => {
380	                e.prevent_default();
381	                completion_candidates.set(Vec::new());
382	                on_submit.emit((*input_value).clone());
383	            }
384	            "ArrowUp" => {
385	                e.prevent_default();
386	                completion_candidates.set(Vec::new());
387	                let cmds = &*cmd_history;
388	                if cmds.is_empty() {
389	                    return;
390	                }
391	                let new_idx = match *cmd_index {
392	                    None => cmds.len() - 1,
393	                    Some(0) => 0,
394	                    Some(i) => i - 1,
395	                };
396	                cmd_index.set(Some(new_idx));
397	                input_value.set(cmds[new_idx].clone());
398	            }
399	            "ArrowDown" => {
400	                e.prevent_default();
401	                completion_candidates.set(Vec::new());
402	                let cmds = &*cmd_history;
403	                match *cmd_index {
404	                    Some(i) if i + 1 < cmds.len() => {
405	                        cmd_index.set(Some(i + 1));
406	                        input_value.set(cmds[i + 1].clone());
407	                    }
408	                    Some(_) => {
409	                        cmd_index.set(None);
410	                        input_value.set(String::new());
411	                    }
412	                    None => {}
413	                }
414	            }
415	            _ => {}
416	        }
417	    })
418	}
