420	/// Saga 33 step 045 (was step 043's `handle_tab`):
421	/// completion keydown handler. Reads cursor pos from the
422	/// underlying HtmlInputElement, runs the candidate pipeline,
423	/// and either inserts a unique completion in-place or pops
424	/// up the multi-match list.
425	fn handle_completion(
426	    e: &KeyboardEvent,
427	    input_value: &UseStateHandle<String>,
428	    completion_candidates: &UseStateHandle<Vec<String>>,
429	) {
430	    let cursor = e
431	        .target()
432	        .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
433	        .and_then(|el| el.selection_start().ok().flatten())
434	        .map(|p| p as usize)
435	        .unwrap_or_else(|| input_value.len());
436	    let value = (**input_value).clone();
437	    // mlpl-eval is wasm-only in this crate (see Cargo.toml).
438	    // On native (tests), the builtin list collapses to empty
439	    // -- pure helpers are covered by completion::tests.
440	    #[cfg(target_arch = "wasm32")]
441	    let builtins: Vec<&str> = mlpl_eval::runtime_builtin_names().collect();
442	    #[cfg(not(target_arch = "wasm32"))]
443	    let builtins: Vec<&str> = Vec::new();
444	    match crate::completion::compute_tab_match(&value, cursor, builtins.iter().copied()) {
445	        crate::completion::TabMatch::None => {
446	            completion_candidates.set(Vec::new());
447	        }
448	        crate::completion::TabMatch::Apply { input, cursor: _ } => {
449	            input_value.set(input);
450	            completion_candidates.set(Vec::new());
451	        }
452	        crate::completion::TabMatch::Popup(v) => {
453	            completion_candidates.set(v);
454	        }
455	    }
456	}
