303	                        <button class={cls(DocTab::Usage)} onclick={setter(DocTab::Usage)}>{"Usage Guide"}</button>
304	                        <button class={cls(DocTab::Glossary)} onclick={setter(DocTab::Glossary)}>{"Glossary"}</button>
305	                        <button class={cls(DocTab::Diagrams)} onclick={setter(DocTab::Diagrams)}>{"Diagrams"}</button>
306	                    </div>
307	                    <button class="close-btn" onclick={props.on_close.clone()} aria-label="Close">{"×"}</button>
308	                </div>
309	                <div class="modal-body">{ body }</div>
310	            </div>
311	        </div>
