//! Saga 33 step 007: outer-shell composer. The html! is split
//! across `render_shell_chrome` (header + mode bar) and
//! `render_shell_footer` (footer + dialog) so each `html!`
//! invocation lives in its own file under the 25-LOC budget.

use yew::prelude::*;

use crate::mode_callbacks;
use crate::render::RenderArgs;
use crate::render_callbacks::InputCallbacks;
use crate::render_main::{MainArgs, render_main};
use crate::render_modes::Modes;
use crate::render_shell_chrome::render_shell_chrome;
use crate::render_shell_footer::render_shell_footer;
use crate::tutorial::run_example;

pub fn render_shell(a: RenderArgs, inputs: InputCallbacks, modes: Modes) -> Html {
    let cb = mode_callbacks::bundle(
        a.ui.lesson_idx.clone(),
        a.ui.path_state.clone(),
        a.ui.tutorial_initial_view.clone(),
        a.callbacks.on_demo.clone(),
    );
    let on_run_example = run_example(a.callbacks.on_submit.clone(), a.ui.input_value.clone());
    let on_pick = make_pick_completion(
        a.ui.input_value.clone(),
        a.ui.completion_candidates.clone(),
        a.ui.completion_selected.clone(),
    );
    let main_args = build_main_args(&a, &cb, &inputs, &modes, on_run_example, on_pick);
    let chrome = render_shell_chrome(&a, &inputs, &modes, &cb);
    let footer = render_shell_footer(*a.ui.dialog_open, inputs.close_dialog);
    html! {
        <>
            { chrome }
            { render_main(main_args) }
            { footer }
        </>
    }
}

fn build_main_args<'a>(
    a: &'a RenderArgs,
    cb: &'a mode_callbacks::ModeCallbacks,
    inputs: &InputCallbacks,
    modes: &Modes,
    on_run_example: Callback<String>,
    on_pick_completion: Callback<String>,
) -> MainArgs<'a> {
    MainArgs {
        tutorial_active: modes.tutorial_active,
        paths_active: modes.paths_active,
        cur_lesson: modes.cur_lesson,
        lesson_idx: a.ui.lesson_idx.clone(),
        initial_view: *a.ui.tutorial_initial_view,
        cur_path: modes.cur_path,
        cb,
        history: &a.active.history,
        input_value: &a.ui.input_value,
        on_input: inputs.on_input.clone(),
        on_keydown: inputs.on_keydown.clone(),
        on_run_example,
        on_run_batch: a.callbacks.on_run_batch.clone(),
        completion_candidates: (*a.ui.completion_candidates).clone(),
        on_pick_completion,
        completion_selected: *a.ui.completion_selected,
    }
}

/// Saga 33 step 043: build the click handler that fires when
/// the user clicks a tab-completion chip. Inserts the chosen
/// completion at the cursor position and clears the popup.
/// Cursor lookup happens at the moment of click against the
/// current input value (we don't track cursor in app state).
fn make_pick_completion(
    input_value: UseStateHandle<String>,
    completion_candidates: UseStateHandle<Vec<String>>,
    completion_selected: UseStateHandle<usize>,
) -> Callback<String> {
    Callback::from(move |chosen: String| {
        let cur = input_value.len();
        let (out, _) = crate::completion::apply_completion(&input_value, cur, &chosen);
        input_value.set(out);
        completion_candidates.set(Vec::new());
        completion_selected.set(0);
    })
}

//! Saga 33 step 007: state-bag struct definitions for the App
//! component. Each struct is constructed by a custom hook in
//! `app_hooks` and read by downstream phases (active_context,
//! build_callbacks, render). The struct-of-structs decomposition
//! preserves type safety: every consumer takes the *specific*
//! sub-state it needs, no `&AppState` god-object passing.

use std::cell::RefCell;
use std::rc::Rc;

use yew::prelude::*;

use crate::components::TutorialView;
use mlpl_wasm::WasmSession;
use mlpl_web_eval::state::HistoryEntry;

/// Two isolated session scratchpads: the main REPL and the
/// tutorial pane. Each has its own `WasmSession` + history so
/// experimentation in the tutorial doesn't pollute the user's
/// main flow.
pub struct Sessions {
    pub main: Rc<RefCell<WasmSession>>,
    pub tutorial: Rc<RefCell<WasmSession>>,
}

/// Reactive UI state allocated via `use_state` hooks. All Yew
/// reactivity flows through these handles.
pub struct UiState {
    pub history: UseStateHandle<Vec<HistoryEntry>>,
    pub tutorial_history: UseStateHandle<Vec<HistoryEntry>>,
    pub input_value: UseStateHandle<String>,
    pub cmd_history: UseStateHandle<Vec<String>>,
    pub cmd_index: UseStateHandle<Option<usize>>,
    pub dialog_open: UseStateHandle<bool>,
    pub lesson_idx: UseStateHandle<Option<usize>>,
    pub tutorial_initial_view: UseStateHandle<TutorialView>,
    pub path_state: UseStateHandle<Option<(Option<usize>, usize)>>,
    /// Saga 33 step 043: candidates for the Tab-completion
    /// popup below the REPL input. Empty Vec = popup hidden.
    pub completion_candidates: UseStateHandle<Vec<String>>,
    /// Saga 33 step 047: highlighted index in the completion
    /// popup. Resets to 0 when new candidates land.
    pub completion_selected: UseStateHandle<usize>,
}

/// Upload-flow state: the hidden `<input type=file>` NodeRef and
/// the pending-name slot that bridges the slash-command handler
/// (sync) and the file picker's async onchange. Saga 29 step 016.
pub struct UploadState {
    pub input_ref: NodeRef,
    pub pending_name: UseStateHandle<Option<String>>,
}

/// Per-render derived "which session and history are active".
/// Computed from `Sessions` + `UiState::lesson_idx`. Owned (cloned)
/// so callback builders can keep their own captures.
pub struct ActiveContext {
    pub session: Rc<RefCell<WasmSession>>,
    pub history: UseStateHandle<Vec<HistoryEntry>>,
    pub in_tutorial: bool,
}

