    });
    let input_h = a.ui.input_value.clone();
    let splash_hide_t = a.onboarding.show_splash.clone();
    let on_type = Callback::from(move |text: String| {
        crate::onboarding_storage::write_splash_dismissed();
        splash_hide_t.set(false);
        input_h.set(text);
    });
    let lesson_h = a.ui.lesson_idx.clone();
    let splash_hide_l = a.onboarding.show_splash.clone();
    let on_tutorial = Callback::from(move |()| {
        crate::onboarding_storage::write_splash_dismissed();
        splash_hide_l.set(false);
        lesson_h.set(Some(0));
    });
    let path_h = a.ui.path_state.clone();
    let splash_hide_p = a.onboarding.show_splash.clone();
    let on_paths = Callback::from(move |()| {
        crate::onboarding_storage::write_splash_dismissed();
        splash_hide_p.set(false);
        path_h.set(Some((None, 0)));
