pub struct TourProps {
    pub step: usize,
    pub on_next: Callback<()>,
    pub on_prev: Callback<()>,
    pub on_close: Callback<()>,
}

#[function_component(TourTooltip)]
pub fn tour_tooltip(props: &TourProps) -> Html {
    let s = &STEPS[props.step.min(STEPS.len() - 1)];
    let pos = target_position(s.target);
    let style = tooltip_style(&pos, s.target);
    let total = STEPS.len();
    let idx = props.step + 1;
    let close = {
        let cb = props.on_close.clone();
        Callback::from(move |_: MouseEvent| cb.emit(()))
    };
    let next = {
        let cb = props.on_next.clone();
        Callback::from(move |_: MouseEvent| cb.emit(()))
    };
    let prev = {
        let cb = props.on_prev.clone();
        Callback::from(move |_: MouseEvent| cb.emit(()))
    };
    html! {
        <>
            <div class="tour-backdrop" onclick={close.clone()} />
            <div class="tour-spotlight" style={spotlight_style(&pos)} />
            <div class="tour-tooltip" style={style}>
                <div class="tour-header">
                    <strong>{ s.title }</strong>
                    <button class="tour-close" onclick={close} aria-label="Close tour">{"x"}</button>
                </div>
                <p class="tour-body">{ s.body }</p>
                <div class="tour-nav">
                    <span class="tour-counter">{format!("{idx} / {total}")}</span>
                    <button class="tour-btn" onclick={prev} disabled={props.step == 0}>{"Back"}</button>
                    <button class="tour-btn tour-btn-primary" onclick={next}>
                        { if props.step + 1 >= total { "Done" } else { "Next" } }
                    </button>
                </div>
            </div>
        </>
    }
}

