55	    let style = tooltip_style(&pos, s.target);
56	    let counter = format!("{} / {}", props.step + 1, STEPS.len());
57	    let done = props.step + 1 >= STEPS.len();
58	    html! {
59	        <>
60	            <div class="tour-backdrop" />
61	            <div class="tour-spotlight" style={spotlight_style(&pos)} />
62	            <div class="tour-tooltip" style={style}>
63	                <div class="tour-header">
64	                    <strong>{ s.title }</strong>
65	                    <button class="tour-close" onclick={props.on_close.clone()} aria-label="Close tour">{"x"}</button>
66	                </div>
67	                <p class="tour-body">{ s.body }</p>
68	                <div class="tour-nav">
69	                    <span class="tour-counter">{ counter }</span>
70	                    <button class="tour-btn" onclick={props.on_prev.clone()} disabled={props.step == 0}>{"Back"}</button>
71	                    <button class="tour-btn tour-btn-primary" onclick={props.on_next.clone()}>
72	                        { if done { "Done" } else { "Next" } }
73	                    </button>
74	                </div>
75	            </div>
76	        </>
77	    }
78	}
