80	struct Rect {
81	    top: f64,
82	    left: f64,
83	    width: f64,
84	    height: f64,
85	}
86	
87	fn target_position(target: &str) -> Rect {
88	    let sel = format!("[data-tour-target='{target}']");
89	    web_sys::window()
90	        .and_then(|w| w.document())
91	        .and_then(|d| d.query_selector(&sel).ok()?)
92	        .map(|el| {
93	            let r = el
94	                .unchecked_into::<web_sys::Element>()
95	                .get_bounding_client_rect();
96	            Rect {
97	                top: r.top(),
98	                left: r.left(),
99	                width: r.width(),
100	                height: r.height(),
101	            }
102	        })
103	        .unwrap_or(Rect {
104	            top: 100.0,
105	            left: 100.0,
106	            width: 200.0,
107	            height: 40.0,
108	        })
109	}
110	
111	fn spotlight_style(r: &Rect) -> String {
112	    let pad = 6.0;
113	    format!(
114	        "top:{}px;left:{}px;width:{}px;height:{}px",
115	        r.top - pad,
116	        r.left - pad,
117	        r.width + pad * 2.0,
118	        r.height + pad * 2.0,
119	    )
120	}
121	
122	fn tooltip_style(r: &Rect, _target: &str) -> String {
123	    let (vw, vh) = viewport_size();
124	    let tw = 340.0;
125	    let th = 180.0;
126	    let below = r.top + r.height + 12.0;
127	    let top = if below + th > vh {
128	        (r.top - th - 12.0).max(8.0)
129	    } else {
130	        below
131	    };
132	    let left = r.left.max(8.0).min(vw - tw - 8.0);
133	    format!("top:{top}px;left:{left}px")
134	}
135	
136	fn viewport_size() -> (f64, f64) {
137	    web_sys::window()
138	        .map(|w| {
139	            let vw = w
140	                .inner_width()
141	                .ok()
142	                .and_then(|v| v.as_f64())
143	                .unwrap_or(1200.0);
144	            let vh = w
145	                .inner_height()
146	                .ok()
147	                .and_then(|v| v.as_f64())
148	                .unwrap_or(800.0);
149	            (vw, vh)
150	        })
151	        .unwrap_or((1200.0, 800.0))
152	}

