#[derive(Serialize)]
pub struct ShapeInfo {
    pub name: String,
    pub shape: Vec<usize>,
    pub rank: usize,
    pub elements: usize,
}

#[derive(Serialize)]
pub struct Stage3dEvent {
    pub step_idx: usize,
    pub label: String,
    pub output: ShapeInfo,
}

pub fn emit(event: &Stage3dEvent) {
    if let Ok(json) = serde_json::to_string(event) {
        let _ = js_sys::eval(&format!("window.__stage3d_add_step('{json}')"));
    }
}

pub fn shape_of(name: &str, arr: &mlpl_array::DenseArray) -> ShapeInfo {
    ShapeInfo {
        name: name.to_string(),
        shape: arr.shape().to_vec(),
        rank: arr.rank(),
        elements: arr.data().len(),
    }
}

