    tutorial_pane: Html,
    paths_pane: Html,
    repl_pane: Html,
) -> Html {
    let stage = if show_3d {
        html! { <section class="stage3d-pane"><Stage3dPanel /></section> }
    } else {
        html! {}
    };
    if tutorial_active {
        html! {
            <main class="tutorial-split">
                <section class="tutorial-pane">{ tutorial_pane }</section>
                <section class="repl-pane">{ repl_pane }{ stage }</section>
            </main>
        }
    } else {
        let cls = if show_3d { "viz3d-split" } else { "" };
        html! {
            <main class={cls}>
                { tutorial_pane }
                { paths_pane }
                { repl_pane }
                { stage }
            </main>
        }
    }
}

