pub fn parse_3d_command(input: &str) -> Option<bool> {
    let lower = input.trim().to_ascii_lowercase();
    match lower.as_str() {
        ":3d" | ":3d on" => Some(true),
        ":2d" | ":3d off" => Some(false),
        _ => None,
    }
}

pub fn is_3d_hotkey(ctrl: bool, code: &str) -> bool {
    ctrl && code == "Digit3"
}

