            new_cmds.push(trimmed.to_string());
            if trimmed == ":clear" {
                deps.session.borrow().clear();
                new_history.clear();
                if *deps.show_3d {
                    let _ = js_sys::eval("window.__stage3d_clear && window.__stage3d_clear()");
