105	/// REPL submissions. Pushes a Running marker, yields, evals,
106	/// replaces marker with result, recurses to next line.
107	fn process_next_eval(
108	    deps: EvalDeps,
109	    mut history: Vec<HistoryEntry>,
110	    queue: Vec<String>,
111	    idx: usize,
112	) {
113	    if idx >= queue.len() {
114	        deps.history.set(history);
