33	
34	pub fn build_shape_info(name: String, shape: Vec<usize>, values: Option<Vec<f64>>) -> ShapeInfo {
35	    let elements = if shape.is_empty() {
36	        1
37	    } else {
38	        shape.iter().product()
39	    };
40	    let (vals, summary) = match values {
41	        Some(ref v) if v.len() <= MAX_INLINE_ELEMENTS => (Some(v.clone()), None),
42	        Some(ref v) => (None, Some(compute_summary(v))),
43	        None => (None, None),
44	    };
45	    ShapeInfo {
46	        name,
47	        shape: shape.clone(),
48	        rank: shape.len(),
49	        elements,
50	        values: vals,
51	        summary,
52	    }
53	}
54	
55	fn compute_summary(data: &[f64]) -> ArraySummary {
56	    let n = data.len() as f64;
57	    let min = data.iter().cloned().fold(f64::INFINITY, f64::min);
58	    let max = data.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
59	    let mean = data.iter().sum::<f64>() / n;
60	    let var = data.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / n;
61	    let std = var.sqrt();
62	    let bins = 16;
63	    let range = if (max - min).abs() < 1e-12 {
64	        1.0
65	    } else {
66	        max - min
67	    };
68	    let mut histogram = vec![0usize; bins];
69	    for &v in data {
70	        let idx = ((v - min) / range * (bins as f64 - 1.0)).round() as usize;
71	        histogram[idx.min(bins - 1)] += 1;
72	    }
73	    ArraySummary {
74	        min,
75	        max,
76	        mean,
77	        std,
78	        histogram,
79	    }
80	}
