97	/// Parse shape from MLPL output. Handles two formats:
98	/// 1. Summary: `<DenseArray shape=[10, 10] elems=100 ...>`
99	/// 2. Values: space-separated rows (`0 1 2\n3 4 5`)
100	pub fn shape_from_output(output: &str) -> (Vec<usize>, usize) {
101	    let trimmed = output.trim();
102	    if trimmed.is_empty() {
103	        return (vec![], 0);
104	    }
105	    if let Some(parsed) = parse_dense_array_summary(trimmed) {
106	        return parsed;
107	    }
108	    let lines: Vec<&str> = trimmed
109	        .lines()
110	        .map(str::trim)
111	        .filter(|l| !l.is_empty())
112	        .collect();
113	    let cols = lines[0].split_whitespace().count();
114	    let elements = lines.len() * cols;
115	    match (lines.len(), cols) {
116	        (1, 1) => (vec![], 1),
117	        (1, _) => (vec![cols], elements),
118	        _ => (vec![lines.len(), cols], elements),
119	    }
120	}
121	
122	fn parse_dense_array_summary(s: &str) -> Option<(Vec<usize>, usize)> {
123	    if !s.starts_with("<DenseArray") {
124	        return None;
125	    }
126	    let shape_start = s.find("shape=[")? + 7;
127	    let shape_end = s[shape_start..].find(']')? + shape_start;
128	    let shape: Vec<usize> = s[shape_start..shape_end]
129	        .split(',')
130	        .filter_map(|p| p.trim().parse().ok())
131	        .collect();
132	    let elems = s
133	        .find("elems=")
134	        .and_then(|i| s[i + 6..].split_whitespace().next()?.parse().ok())
135	        .unwrap_or_else(|| shape.iter().product());
136	    Some((shape, elems))
137	}
