30	/// Single-line submit: thin wrapper that pipes the line through
31	/// the batch path so there is exactly one place that mutates
32	/// state. Calling `make_submit` N times in a tight loop USED
33	/// to drop N-1 history entries because each call did
34	/// `(*deps.history).clone()` -> push one -> `set(new)` --
35	/// inside one event tick every clone read the same snapshot
36	/// and only the last `set` won (Tutorial Run-All bug, May 7
37	/// 2026). Routing through `make_submit_batch` collapses any
38	/// number of lines into a single read-modify-write.
39	pub fn make_submit(deps: EvalDeps) -> Callback<String> {
40	    let batch = make_submit_batch(deps);
41	    Callback::from(move |line: String| batch.emit(vec![line]))
42	}
43	
44	/// Evaluate every line in `lines` against the current session
45	/// in one pass, then commit all four state handles exactly
46	/// once. Empty/whitespace-only lines are skipped (matching
47	/// single-line submit semantics); `:clear` and `:help` are
48	/// honored mid-batch.
49	pub fn make_submit_batch(deps: EvalDeps) -> Callback<Vec<String>> {
50	    Callback::from(move |lines: Vec<String>| {
51	        let mut new_history = (*deps.history).clone();
52	        let mut new_cmds = (*deps.cmd_history).clone();
53	        let mut eval_queue: Vec<String> = Vec::new();
54	        for line in lines {
55	            let trimmed = line.trim();
56	            if trimmed.is_empty() {
57	                continue;
58	            }
59	            new_cmds.push(trimmed.to_string());
60	            if trimmed == ":clear" {
61	                deps.session.borrow().clear();
62	                new_history.clear();
63	                if *deps.show_3d {
64	                    let _ = js_sys::eval("window.__stage3d_clear && window.__stage3d_clear()");
65	                }
66	                continue;
67	            }
68	            if let Some(cmd) = crate::viz3d_toggle::parse_3d_command(trimmed) {
69	                match cmd {
70	                    crate::viz3d_toggle::Viz3dCmd::On => deps.show_3d.set(true),
71	                    crate::viz3d_toggle::Viz3dCmd::Off => deps.show_3d.set(false),
72	                    crate::viz3d_toggle::Viz3dCmd::Reset => {
73	                        let _ = js_sys::eval(
74	                            "window.__stage3d_reset_view && window.__stage3d_reset_view()",
75	                        );
76	                    }
77	                }
78	                continue;
79	            }
80	            if let Some(name) = parse_upload_command(trimmed) {
81	                new_history.push(handle_upload_command(&deps, trimmed, &name));
82	                continue;
83	            }
84	            // Anything else hits the WASM evaluator, which may
85	            // block for seconds; defer to the spinner pipeline
86	            // (Saga 29 step 018) so the user sees a running
87	            // indicator instead of a frozen page.
88	            eval_queue.push(trimmed.to_string());
89	        }
90	        if new_cmds.is_empty() {
91	            return;
92	        }
93	        deps.cmd_history.set(new_cmds);
94	        deps.cmd_index.set(None);
95	        deps.input_value.set(String::new());
96	        if eval_queue.is_empty() {
97	            deps.history.set(new_history);
98	            return;
99	        }
100	        process_next_eval(deps.clone(), new_history, eval_queue, 0);
101	    })
102	}
