76	    let mut had = false;
77	    for note in crate::demos::progress_notes_for(demo_name, idx) {
78	        entries.push(HistoryEntry {
79	            input: note.heading.to_string(),
80	            output: note.body.to_string(),
81	            is_error: false,
82	            kind: EntryKind::Narration,
83	        });
84	        had = true;
85	    }
