89	fn schedule_demo_line(
90	    session: Rc<RefCell<WasmSession>>,
91	    history: UseStateHandle<Vec<HistoryEntry>>,
92	    mut entries: Vec<HistoryEntry>,
93	    demo: &'static crate::demos::Demo,
94	    idx: usize,
95	) {
96	    let lines = demo.lines;
97	    if idx >= lines.len() {
98	        // Last line ran -- append the takeaway narration panel
99	        // and paint the final history state.
100	        entries.push(HistoryEntry {
101	            input: "What just happened".to_string(),
102	            output: demo.takeaway.to_string(),
103	            is_error: false,
104	            kind: EntryKind::Narration,
105	        });
106	        history.set(entries);
107	        return;
108	    }
109	    push_progress_notes(&mut entries, demo.name, idx);
110	    let line = lines[idx];
111	    push_running_marker(&mut entries, line);
112	    history.set(entries.clone());
113	    let session_next = Rc::clone(&session);
114	    let history_next = history.clone();
115	    gloo::timers::callback::Timeout::new(0, move || {
116	        let r = session.borrow().eval_with_values(line);
117	        let is_error = r.display.starts_with("error:");
118	        if !is_error {
119	            let name = line.split('=').next().unwrap_or(line).trim().to_string();
120	            let info = crate::viz3d_events::build_shape_info(name, r.shape, r.values);
121	            crate::viz3d_events::emit(&crate::viz3d_events::Stage3dEvent {
122	                step_idx: 0,
123	                label: line.to_string(),
124	                output: info,
125	            });
126	        }
127	        replace_running_with_result(&mut entries, line, r.display);
128	        history.set(entries.clone());
129	        schedule_demo_line(session_next, history_next, entries, demo, idx + 1);
130	    })
131	    .forget();
132	}

