1	//! Math and constructor built-in functions.
2	
3	use mlpl_array::{DenseArray, Shape};
4	
5	use mlpl_runtime_core::error::RuntimeError;
6	
7	/// Every name dispatched by [`try_call`]. Kept in sync with the
8	/// `match name { ... }` block by hand -- a coverage test in
9	/// `mlpl-eval/tests/help_completeness_tests.rs` asserts each
10	/// entry is documented in `docs/lang-reference.md`.
11	pub(crate) const NAMES: &[&str] = &[
12	    "exp",
13	    "log",
14	    "sqrt",
15	    "abs",
16	    "sigmoid",
17	    "tanh_fn",
18	    "pow",
19	    "gt",
20	    "lt",
21	    "eq",
22	    "mean",
23	    "zeros",
24	    "ones",
25	    "fill",
26	    "cosine_schedule",
27	    "linear_warmup",
28	    "concat",
29	    "last_row",
30	];
31	
32	/// Dispatch math and constructor built-ins. Returns None if not matched.
33	pub(crate) fn try_call(
34	    name: &str,
35	    args: Vec<DenseArray>,
36	) -> Option<Result<DenseArray, RuntimeError>> {
37	    match name {
38	        "exp" => Some(unary(name, args, f64::exp)),
39	        "log" => Some(unary(name, args, f64::ln)),
40	        "sqrt" => Some(unary(name, args, f64::sqrt)),
41	        "abs" => Some(unary(name, args, f64::abs)),
42	        "sigmoid" => Some(unary(name, args, |x| 1.0 / (1.0 + (-x).exp()))),
43	        "tanh_fn" => Some(unary(name, args, f64::tanh)),
44	        "pow" => Some(binary_pow(name, args)),
45	        "gt" => Some(binary_cmp(name, args, |a, b| if a > b { 1.0 } else { 0.0 })),
46	        "lt" => Some(binary_cmp(name, args, |a, b| if a < b { 1.0 } else { 0.0 })),
47	        "eq" => Some(binary_cmp(name, args, |a, b| {
48	            if (a - b).abs() < f64::EPSILON {
49	                1.0
50	            } else {
51	                0.0
52	            }
53	        })),
54	        "mean" => Some(builtin_mean(name, args)),
55	        "zeros" | "ones" | "fill" => Some(constructor(name, args)),
56	        "cosine_schedule" | "linear_warmup" => Some(schedule(name, args)),
57	        // Saga 29 step 005: the 2-arg `concat(a, b)` is the
58	        // original Saga 13 generation-loop helper for rank-0/1
59	        // arrays. The new 3-arg `concat(a, b, axis)` is the
60	        // tape-differentiable axis-aware form, dispatched by
61	        // `builtins.rs` -- let it fall through here.
62	        "concat" if args.len() != 3 => Some(array_util(name, args)),
63	        "last_row" => Some(array_util(name, args)),
64	        _ => None,
65	    }
66	}
67	
68	fn unary(name: &str, args: Vec<DenseArray>, f: fn(f64) -> f64) -> Result<DenseArray, RuntimeError> {
69	    if args.len() != 1 {
70	        return Err(RuntimeError::ArityMismatch {
71	            func: name.into(),
72	            expected: 1,
73	            got: args.len(),
74	        });
75	    }
76	    Ok(args[0].map(f))
77	}
78	
79	fn binary_pow(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
80	    if args.len() != 2 {
81	        return Err(RuntimeError::ArityMismatch {
82	            func: name.into(),
83	            expected: 2,
84	            got: args.len(),
85	        });
86	    }
87	    Ok(args[0].apply_binop(&args[1], f64::powf)?)
88	}
89	
90	fn binary_cmp(
91	    name: &str,
92	    args: Vec<DenseArray>,
93	    f: fn(f64, f64) -> f64,
94	) -> Result<DenseArray, RuntimeError> {
95	    if args.len() != 2 {
96	        return Err(RuntimeError::ArityMismatch {
97	            func: name.into(),
98	            expected: 2,
99	            got: args.len(),
100	        });
101	    }
102	    Ok(args[0].apply_binop(&args[1], f)?)
103	}
104	
105	fn builtin_mean(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
106	    if args.len() != 1 {
107	        return Err(RuntimeError::ArityMismatch {
108	            func: name.into(),
109	            expected: 1,
110	            got: args.len(),
111	        });
112	    }
113	    let data = args[0].data();
114	    let sum: f64 = data.iter().sum();
115	    let count = data.len().max(1) as f64;
116	    Ok(DenseArray::from_scalar(sum / count))
117	}
118	
119	/// Pure scalar learning-rate schedule built-ins.
120	///
121	/// - `cosine_schedule(step, total, lr_min, lr_max)`:
122	///   `lr_min + 0.5*(lr_max - lr_min)*(1 + cos(pi * step/total))`,
123	///   clamped to `[lr_min, lr_max]` for `step` outside `[0, total]`.
124	/// - `linear_warmup(step, warmup, lr)`:
125	///   `lr * min(1, step/warmup)`, clamped to `[0, lr]`.
126	fn schedule(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
127	    let expected = if name == "cosine_schedule" { 4 } else { 3 };
128	    if args.len() != expected {
129	        return Err(RuntimeError::ArityMismatch {
130	            func: name.into(),
131	            expected,
132	            got: args.len(),
133	        });
134	    }
135	    for (i, a) in args.iter().enumerate() {
136	        if a.rank() != 0 {
137	            return Err(RuntimeError::InvalidArgument {
138	                func: name.into(),
139	                reason: format!("argument {i} must be a scalar, got rank {}", a.rank()),
140	            });
141	        }
142	    }
143	    let v = if name == "cosine_schedule" {
144	        let step = args[0].data()[0];
145	        let total = args[1].data()[0];
146	        let lr_min = args[2].data()[0];
147	        let lr_max = args[3].data()[0];
148	        if total <= 0.0 {
149	            lr_max
150	        } else {
151	            let t = step.clamp(0.0, total) / total;
152	            lr_min + 0.5 * (lr_max - lr_min) * (1.0 + (std::f64::consts::PI * t).cos())
153	        }
154	    } else {
155	        let step = args[0].data()[0];
156	        let warmup = args[1].data()[0];
157	        let lr = args[2].data()[0];
158	        if warmup <= 0.0 {
159	            lr
160	        } else {
161	            lr * (step / warmup).clamp(0.0, 1.0)
162	        }
163	    };
164	    Ok(DenseArray::from_scalar(v))
165	}
166	
167	/// `concat(a, b)` and `last_row(matrix)` -- array utilities for
168	/// generation loops. `concat` joins two rank-0/1 arrays into a 1-D
169	/// vector; `last_row` extracts the final row of a rank-2 matrix.
170	fn array_util(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
171	    if name == "concat" {
172	        if args.len() != 2 {
173	            return Err(RuntimeError::ArityMismatch {
174	                func: name.into(),
175	                expected: 2,
176	                got: args.len(),
177	            });
178	        }
179	        for (i, a) in args.iter().enumerate() {
180	            if a.rank() > 1 {
181	                return Err(RuntimeError::InvalidArgument {
182	                    func: name.into(),
183	                    reason: format!("argument {i} must be rank 0 or 1, got rank {}", a.rank()),
184	                });
185	            }
186	        }
187	        let mut data = Vec::with_capacity(args[0].data().len() + args[1].data().len());
188	        data.extend_from_slice(args[0].data());
189	        data.extend_from_slice(args[1].data());
190	        Ok(DenseArray::from_vec(data))
191	    } else {
192	        // last_row
193	        if args.len() != 1 {
194	            return Err(RuntimeError::ArityMismatch {
195	                func: name.into(),
196	                expected: 1,
197	                got: args.len(),
198	            });
199	        }
200	        if args[0].rank() != 2 {
201	            return Err(RuntimeError::InvalidArgument {
202	                func: name.into(),
203	                reason: format!("expected rank-2 matrix, got rank {}", args[0].rank()),
204	            });
205	        }
206	        let cols = args[0].shape().dims()[1];
207	        let data = args[0].data();
208	        Ok(DenseArray::from_vec(data[data.len() - cols..].to_vec()))
209	    }
210	}
211	
212	fn constructor(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
213	    if name == "fill" {
214	        if args.len() != 2 {
215	            return Err(RuntimeError::ArityMismatch {
216	                func: name.into(),
217	                expected: 2,
218	                got: args.len(),
219	            });
220	        }
221	        if args[1].rank() != 0 {
222	            return Err(RuntimeError::InvalidArgument {
223	                func: name.into(),
224	                reason: "value must be scalar".into(),
225	            });
226	        }
227	        let dims: Vec<usize> = args[0].data().iter().map(|&d| d as usize).collect();
228	        let count = dims.iter().product();
229	        Ok(DenseArray::new(
230	            Shape::new(dims),
231	            vec![args[1].data()[0]; count],
232	        )?)
233	    } else {
234	        if args.len() != 1 {
235	            return Err(RuntimeError::ArityMismatch {
236	                func: name.into(),
237	                expected: 1,
238	                got: args.len(),
239	            });
240	        }
